css:
body{
    width: 610px;
}            

.row {

  margin-left:-5px;
  margin-right:-5px;
}

.column {
  float: left;
  width: 365px;
  padding: 5px;
  margin-bottom: 20px; 
  position:relative;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
  width: 95%;
  border: 1px solid #A9A9A9;
  font-family: sans-serif;
}

th, td {
  text-align: left;
  padding: 3px;
  border: 1px solid #A9A9A9;
  font-family: sans-serif;
  font-size:12px;
}

.backcolor {
  background-color: #D3D3D3;
}

.wrapper {
  background-color: white;
   border: solid 1px green; 
}

#table-1{
  float: left;
  width: 95%;
  padding: 5px;
  margin-left:-5px;
  margin-right:-5px;
  margin-bottom: 50px;
  font-family: sans-serif;
}

#table-2{
  float: left;
  width: 95%;
  padding: 5px;
  margin-left:-5px;
  margin-right:-5px;
  font-family: sans-serif;
}

#zero-table{
  float: right;
  width: 95%;
  padding: 5px;
  margin-left:-5px;
  margin-right:-5px;
  font-family: sans-serif;
}


.address{
    width: 200px;
    font-size:16px;
}

